<?php declare(strict_types=1);
use Kulturhus\Verein\{BalancePeriodLedger,BalanceFilingCommands};
use Kulturhus\Native\Shared\Db;
putenv('VEREIN_BALANCE_PERIODS=1');
Db::run($db,"INSERT INTO club_settings(club_id,section,payload,version,updated_at) VALUES('foreign-balance-environment','tax',?,1,UTC_TIMESTAMP())",[json_encode($taxSettings,JSON_THROW_ON_ERROR)]);
$periodLedger=new BalancePeriodLedger($db,'env-foreign');
$periodId=$periodLedger->create(['start'=>'2025-01-01','end'=>'2025-12-31'],'Own full-month original period',true);
$periodLedger->setup($periodId,1,$pair('cash','equity',70000),'Own original period opening',true);
$periodReport=$periodLedger->report($periodId);
$periodLedger->close($periodId,2,$periodReport['journal_sha256'],['complete'=>true,'valuation'=>true,'cutoff'=>true,'tax'=>true],'Own original approved period');
$periodCommand=new BalanceFilingCommands($db,'env-foreign',$policy);$periodWorkspace=$periodCommand->workspace(2025,null,$periodId);
$prove($periodWorkspace['context']['period_id']===$periodId&&$periodId==='20250101-20251231','actual canonical dated period identity is retained, independently of random filing identifiers');
$periodInput=['action'=>'tax-filing-balance-create','context'=>$periodWorkspace['context'],'values'=>['balance_scope'=>'separate_business_ledger','environment'=>'production']];$periodKey=bin2hex(random_bytes(16));
$periodResult=$periodCommand->run($periodInput,$periodKey);
$prove($periodResult['result']['form_data']['balance_preparation']['period_id']===$periodId&&$periodResult['result']['tax_year']===2025&&$periodResult['result']['version']===1,'actual complete-month closing creates its separately bound first local E-balance');
$before=ownOriginalDatabaseHash($db,$allTables);
$prove($periodCommand->run($periodInput,$periodKey)===$periodResult&&ownOriginalDatabaseHash($db,$allTables)===$before,'actual identical dated-period creation retry reads the same first without another filing');
$foreignFiling=$periodResult['result']['id'];$detail=$periodCommand->workspace(2025,$foreignFiling);
$prove($detail['context']['period_id']===$periodId,'existing dated E-balance detail keeps the canonical original period');
$refuse(fn()=>$periodCommand->workspace(2025,null,str_repeat('a',32)),'random filing-style identity cannot replace a real dated period',422);
$refuse(fn()=>$periodCommand->workspace(2026,null,$periodId),'another closing year cannot replace the original period year',409);
putenv('VEREIN_BALANCE_PERIODS=0');
